actual_acquired_program_and_units.program:
def _known_bool(facts, key):
    value = facts.get(key, None)
    if isinstance(value, bool):
        return value
    return None


def _known_number(facts, key):
    value = facts.get(key, None)
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    return None


def _bool_options(value):
    if isinstance(value, bool):
        return [value]
    return [False, True]


def _tri_and(values):
    for value in values:
        if value is False:
            return False
    for value in values:
        if value is None:
            return None
    return True


def _tri_or(values):
    for value in values:
        if value is True:
            return True
    for value in values:
        if value is None:
            return None
    return False


def _unique(values):
    answer = []
    for value in values:
        if value not in answer:
            answer.append(value)
    return answer


def _result(value, used_units, open_dependencies):
    if value is not None:
        open_dependencies = []
    return {
        "value": value,
        "used_units": _unique(used_units),
        "open_dependencies": _unique(open_dependencies)
    }


def _married_status(facts):
    separated = _known_bool(facts, "legally_separated_under_decree")
    married = _known_bool(facts, "taxpayer_married")
    if separated is True:
        return False
    if isinstance(married, bool):
        return married
    return None


def _married_dependencies(facts):
    if _married_status(facts) is not None:
        return []
    dependencies = []
    if _known_bool(facts, "taxpayer_married") is None:
        dependencies.append("taxpayer_married")
    if _known_bool(facts, "legally_separated_under_decree") is None:
        dependencies.append("legally_separated_under_decree")
    return dependencies


def _surviving_derived_status(facts):
    died = _known_bool(facts, "spouse_died_in_either_prior_two_years")
    home = _known_bool(facts, "maintained_home_for_listed_child_dependent")
    half = _known_bool(facts, "furnished_over_half_home_cost")
    remarried = _known_bool(facts, "remarried_before_year_end")
    joint_possible = _known_bool(facts, "death_year_joint_return_possible")
    not_remarried = None if remarried is None else not remarried
    return _tri_and([died, home, half, not_remarried, joint_possible])


def _surviving_status(facts):
    direct = _known_bool(facts, "taxpayer_is_surviving_spouse")
    if isinstance(direct, bool):
        return direct
    return _surviving_derived_status(facts)


def _surviving_dependencies(facts, allow_direct):
    if allow_direct and _known_bool(facts, "taxpayer_is_surviving_spouse") is not None:
        return []
    if _surviving_derived_status(facts) is not None:
        return []
    dependencies = []
    if allow_direct:
        dependencies.append("taxpayer_is_surviving_spouse")
    for key in [
        "spouse_died_in_either_prior_two_years",
        "maintained_home_for_listed_child_dependent",
        "furnished_over_half_home_cost",
        "remarried_before_year_end",
        "death_year_joint_return_possible"
    ]:
        if _known_bool(facts, key) is None:
            dependencies.append(key)
    return dependencies


def _spouse_exemption_from_components(facts):
    joint = _known_bool(facts, "joint_return_made")
    no_income = _known_bool(facts, "spouse_had_no_gross_income")
    dependent = _known_bool(facts, "spouse_dependent_of_another_taxpayer")
    no_joint = None if joint is None else not joint
    not_dependent = None if dependent is None else not dependent
    return _tri_and([no_joint, no_income, not_dependent])


def _spouse_exemption_status(facts):
    direct = _known_bool(facts, "spouse_exemption_allowable")
    if isinstance(direct, bool):
        return direct
    return _spouse_exemption_from_components(facts)


def _spouse_exemption_dependencies(facts, allow_direct):
    if allow_direct and _known_bool(facts, "spouse_exemption_allowable") is not None:
        return []
    if _spouse_exemption_from_components(facts) is not None:
        return []
    dependencies = []
    if allow_direct:
        dependencies.append("spouse_exemption_allowable")
    for key in [
        "joint_return_made",
        "spouse_had_no_gross_income",
        "spouse_dependent_of_another_taxpayer"
    ]:
        if _known_bool(facts, key) is None:
            dependencies.append(key)
    return dependencies


def _higher_rate_condition(facts):
    married = _married_status(facts)
    surviving = _surviving_status(facts)
    not_married = None if married is None else not married
    not_surviving = None if surviving is None else not surviving
    return _tri_and([not_married, not_surviving])


def _rate_value(facts):
    higher = _higher_rate_condition(facts)
    if higher is True:
        return 750.0
    if higher is False:
        return 600.0
    return None


def _rate_dependencies(facts):
    if _rate_value(facts) is not None:
        return []
    dependencies = []
    if _married_status(facts) is None:
        dependencies.extend(_married_dependencies(facts))
    if _surviving_status(facts) is None:
        dependencies.extend(_surviving_dependencies(facts, True))
    if len(dependencies) == 0:
        dependencies.append("facts determining the applicable section 63(f) amount")
    return _unique(dependencies)


def _rate_used_units(facts):
    used = ["U63_F3"]
    if _known_bool(facts, "legally_separated_under_decree") is True or _known_bool(facts, "taxpayer_married") is None:
        used.append("U7703_A2")
    if _married_status(facts) is not True:
        used.append("U2_A")
    return used


def _self_contribution(facts, qualification_key, unit_id):
    qualified = _known_bool(facts, qualification_key)
    if qualified is False:
        return _result(0.0, [unit_id], [])
    rate = _rate_value(facts)
    used = [unit_id]
    used.extend(_rate_used_units(facts))
    if qualified is True and rate is not None:
        return _result(rate, used, [])
    dependencies = []
    if qualified is None:
        dependencies.append(qualification_key)
    if rate is None:
        dependencies.extend(_rate_dependencies(facts))
    return _result(None, used, dependencies)


def _spouse_contribution(facts, qualification_key, unit_id):
    married = _married_status(facts)
    qualified = _known_bool(facts, qualification_key)
    exemption = _spouse_exemption_status(facts)
    entitled = _tri_and([married, qualified, exemption])
    used = [unit_id, "U151_B", "U7703_A2"]
    if entitled is True:
        return _result(600.0, used, [])
    if entitled is False:
        return _result(0.0, used, [])
    dependencies = []
    if married is None:
        dependencies.extend(_married_dependencies(facts))
    if qualified is None:
        dependencies.append(qualification_key)
    if exemption is None:
        dependencies.extend(_spouse_exemption_dependencies(facts, True))
    return _result(None, used, dependencies)


def _spouse_exemption_options(facts):
    value = _spouse_exemption_status(facts)
    return _bool_options(value)


def _raw_additional_values(facts):
    married_options = _bool_options(_married_status(facts))
    surviving_options = _bool_options(_surviving_status(facts))
    aged_options = _bool_options(_known_bool(facts, "taxpayer_attained_65_before_close"))
    blind_options = _bool_options(_known_bool(facts, "taxpayer_blind_at_close"))
    spouse_aged_options = _bool_options(_known_bool(facts, "spouse_attained_65_before_close"))
    spouse_blind_options = _bool_options(_known_bool(facts, "spouse_blind_at_required_time"))
    exemption_options = _spouse_exemption_options(facts)
    amounts = set()
    for married in married_options:
        for surviving in surviving_options:
            rate = 750.0 if (not married and not surviving) else 600.0
            for aged in aged_options:
                for blind in blind_options:
                    if married:
                        for spouse_aged in spouse_aged_options:
                            for spouse_blind in spouse_blind_options:
                                for exemption in exemption_options:
                                    count = int(aged) + int(blind)
                                    count = count + int(spouse_aged and exemption)
                                    count = count + int(spouse_blind and exemption)
                                    amounts.add(rate * count)
                    else:
                        amounts.add(rate * (int(aged) + int(blind)))
    return sorted(amounts), married_options


def _raw_additional_dependencies(facts, married_options):
    dependencies = []
    if _married_status(facts) is None:
        dependencies.extend(_married_dependencies(facts))
    if False in married_options and _surviving_status(facts) is None:
        dependencies.extend(_surviving_dependencies(facts, True))
    for key in ["taxpayer_attained_65_before_close", "taxpayer_blind_at_close"]:
        if _known_bool(facts, key) is None:
            dependencies.append(key)
    if True in married_options:
        for key in ["spouse_attained_65_before_close", "spouse_blind_at_required_time"]:
            if _known_bool(facts, key) is None:
                dependencies.append(key)
        spouse_may_qualify = (
            _known_bool(facts, "spouse_attained_65_before_close") is not False or
            _known_bool(facts, "spouse_blind_at_required_time") is not False
        )
        if spouse_may_qualify and _spouse_exemption_status(facts) is None:
            dependencies.extend(_spouse_exemption_dependencies(facts, True))
    return _unique(dependencies)


def _given_c3_value(facts):
    candidates = set()
    total = _known_number(facts, "stated_total_additional_standard_deduction_amount")
    if total is not None:
        candidates.add(total)
    self_amount = _known_number(facts, "stated_self_additional_standard_deduction_amount")
    spouse_amount = _known_number(facts, "stated_spouse_additional_standard_deduction_amount")
    if self_amount is not None and spouse_amount is not None:
        candidates.add(self_amount + spouse_amount)
    if len(candidates) == 0:
        return None, [], False
    if len(candidates) > 1:
        return None, ["inconsistent explicitly stated additional-standard-deduction amounts"], True
    return sorted(candidates)[0], [], True


def unit_7703_a_2(facts):
    separated = _known_bool(facts, "legally_separated_under_decree")
    if separated is None:
        return _result(None, ["U7703_A2"], ["legally_separated_under_decree"])
    return _result(separated, ["U7703_A2"], [])


def unit_2_a(facts):
    value = _surviving_derived_status(facts)
    if value is None:
        return _result(None, ["U2_A"], _surviving_dependencies(facts, False))
    return _result(value, ["U2_A"], [])


def unit_151_b(facts):
    value = _spouse_exemption_from_components(facts)
    if value is None:
        return _result(None, ["U151_B"], _spouse_exemption_dependencies(facts, False))
    return _result(value, ["U151_B"], [])


def unit_63_f_3(facts):
    value = _rate_value(facts)
    used = _rate_used_units(facts)
    if value is None:
        return _result(None, used, _rate_dependencies(facts))
    return _result(value, used, [])


def unit_63_f_1_a(facts):
    return _self_contribution(facts, "taxpayer_attained_65_before_close", "U63_F1_A")


def unit_63_f_1_b(facts):
    return _spouse_contribution(facts, "spouse_attained_65_before_close", "U63_F1_B")


def unit_63_f_2_a(facts):
    return _self_contribution(facts, "taxpayer_blind_at_close", "U63_F2_A")


def unit_63_f_2_b(facts):
    return _spouse_contribution(facts, "spouse_blind_at_required_time", "U63_F2_B")


def unit_63_c_6_a(facts):
    married = _married_status(facts)
    separate = _known_bool(facts, "filed_separate_return")
    either_itemizes = _tri_or([
        _known_bool(facts, "taxpayer_itemized_deductions"),
        _known_bool(facts, "spouse_itemized_deductions")
    ])
    value = _tri_and([married, separate, either_itemizes])
    used = ["U63_C6_A"]
    if _known_bool(facts, "legally_separated_under_decree") is True or _known_bool(facts, "taxpayer_married") is None:
        used.append("U7703_A2")
    if value is not None:
        return _result(value, used, [])
    dependencies = []
    if married is None:
        dependencies.extend(_married_dependencies(facts))
    if separate is None:
        dependencies.append("filed_separate_return")
    if either_itemizes is None:
        if _known_bool(facts, "taxpayer_itemized_deductions") is None:
            dependencies.append("taxpayer_itemized_deductions")
        if _known_bool(facts, "spouse_itemized_deductions") is None:
            dependencies.append("spouse_itemized_deductions")
    return _result(None, used, dependencies)


def unit_63_c_3(facts):
    given_value, given_dependencies, has_complete_given = _given_c3_value(facts)
    if has_complete_given:
        return _result(given_value, ["U63_C3"], given_dependencies)
    values, married_options = _raw_additional_values(facts)
    used = [
        "U63_C3",
        "U63_F1_A",
        "U63_F1_B",
        "U63_F2_A",
        "U63_F2_B",
        "U63_F3",
        "U151_B",
        "U7703_A2",
        "U2_A"
    ]
    if len(values) == 1:
        return _result(values[0], used, [])
    dependencies = _raw_additional_dependencies(facts, married_options)
    if len(dependencies) == 0:
        dependencies.append("additional-standard-deduction facts needed to select one statutory amount")
    return _result(None, used, dependencies)


def apply(inputs, premises):
    if not isinstance(inputs, dict):
        return _result(None, [], ["inputs must be an object containing unit and facts"])
    unit = inputs.get("unit", None)
    facts = inputs.get("facts", {})
    if not isinstance(facts, dict):
        return _result(None, [], ["facts must be an object"])
    if unit == "U63_C6_A":
        return unit_63_c_6_a(facts)
    if unit == "U63_C3":
        return unit_63_c_3(facts)
    if unit == "U63_F1_A":
        return unit_63_f_1_a(facts)
    if unit == "U63_F1_B":
        return unit_63_f_1_b(facts)
    if unit == "U63_F2_A":
        return unit_63_f_2_a(facts)
    if unit == "U63_F2_B":
        return unit_63_f_2_b(facts)
    if unit == "U63_F3":
        return unit_63_f_3(facts)
    if unit == "U151_B":
        return unit_151_b(facts)
    if unit == "U7703_A2":
        return unit_7703_a_2(facts)
    if unit == "U2_A":
        return unit_2_a(facts)
    return _result(None, [], ["unknown acquired unit"])
